<template><view class="timer"><text class="title">工作计时 · {{elapsed}}</text><text v-if="state && state.active">{{state.active.description || '工作记录'}} · 案件{{state.active.caseId || '未关联'}}</text><input v-if="!state || !state.active" v-model="description" maxlength="500" placeholder="工作内容备注（选填）" placeholder-style="color:#606266;font-size:16px;"/><button :disabled="loading||busy||!state" :loading="busy" type="primary" @click="action">{{state && state.active?'停止计时':'开始计时'}}</button><button size="mini" :disabled="busy||loading" @click="load(false)">恢复 / 刷新状态</button><text v-if="error" class="error">{{error}}</text><text v-if="state">今日 {{duration(state.daySeconds)}} · 本周 {{duration(state.weekSeconds)}} · {{caseId?'本案件':'累计'}} {{duration(state.totalSeconds)}}</text><text class="link" @click="expanded=!expanded">计时历史（{{state?state.total:0}}条）{{expanded?'收起':'展开'}}</text><view v-if="expanded"><view v-for="r in rows" :key="r.id" class="record" @click="open(r)">{{date(r.startTime)}} · {{r.endTime?duration(r.durationSeconds):'进行中'}} · {{r.description || '工作记录'}}<text v-if="r.caseId"> · 查看案件 ›</text></view><text v-if="!rows.length">暂无计时，从案件或会话开始记录</text><button v-if="state && rows.length<state.total" :disabled="loading" @click="load(true)">加载更多</button></view></view></template>
<script>
export default{props:{caseId:{type:String,default:''},sessionId:{type:[String,Number],default:''},refreshKey:{type:Number,default:0}},data(){return{state:null,rows:[],page:1,description:'',busy:false,loading:false,error:'',now:Date.now(),offset:0,expanded:false};},computed:{elapsed(){return this.state&&this.state.active?this.duration((this.now+this.offset-Date.parse(this.state.active.startTime))/1000):'未在计时';}},watch:{refreshKey(){this.load(false);},caseId(){this.reset();},sessionId(){this.reset();}},mounted(){this._owner=uni.getStorageSync('token');this.load(false);this._tick=setInterval(()=>{this.now=Date.now();if(this._owner!==uni.getStorageSync('token')){this._owner=uni.getStorageSync('token');this.reset();}},1000);this._poll=setInterval(()=>this.load(false,true),30000);},beforeDestroy(){this._disposed=true;clearInterval(this._tick);clearInterval(this._poll);},methods:{duration(n){const s=Math.max(0,Math.floor(n));return Math.floor(s/3600)+'时'+Math.floor(s%3600/60)+'分'+s%60+'秒';},date(s){return new Date(Date.parse(s)+8*3600000).toISOString().slice(0,16).replace('T',' ');},open(r){if(r.caseId)uni.navigateTo({url:'/pages/cases/index?id='+encodeURIComponent(r.caseId)});},reset(){this._version=(this._version||0)+1;this.state=null;this.rows=[];this.page=1;this.description='';this.load(false);},async api(path='',method='GET',data={}){const r=await this.$request('/lawyer/time'+path,method,data,{'content-type':'application/json'});if(!r||r.code!==200)throw new Error(r&&r.msg||'计时操作失败');return r.data;},async load(append=false,background=false){if(this.loading||this._disposed)return;this.loading=true;this.error='';const version=this._version,p=append?this.page+1:1;try{const r=await this.api('','GET',{pageNum:p,...(this.caseId?{caseId:this.caseId}:{})});if(this._disposed||version!==this._version)return;this.state=r;this.offset=Date.parse(r.serverNow)-Date.now();if(background&&this.page>1){this.rows=this.rows.map(old=>r.rows.find(n=>String(n.id)===String(old.id))||old);}else{const combined=append?this.rows.concat(r.rows):r.rows,seen={};this.rows=combined.filter(item=>{if(seen[item.id])return false;seen[item.id]=true;return true;});this.page=p;}}catch(e){if(!this._disposed&&version===this._version)this.error=e.message;}finally{this.loading=false;if(version!==this._version&&!this._disposed)this.load(false);}},async action(){if(this.busy||this.loading||!this.state)return;this.busy=true;this.error='';try{if(this.state.active)await this.api('/'+this.state.active.id+'/stop','POST',{});else await this.api('/start','POST',{caseId:this.caseId||null,sessionId:this.sessionId||null,description:this.description});await this.load(false);}catch(e){this.error=e.message+'；请刷新状态重试，服务端会保留计时。';}finally{this.busy=false;}}}};
</script>
<style scoped>.timer{padding:26rpx;margin:24rpx 0;background:white;border-radius:20rpx;font-size:16px}.timer>text{display:block;margin:14rpx 0}.title{font-size:16px;font-weight:600}input{padding:20rpx;background:var(--brand-background)}.timer button{font-size:16px;margin:16rpx 0}.error{color:var(--brand-danger)}.link{color:var(--brand-link)}.record{padding:16rpx 0;border-bottom:1px solid #eee}</style>

<style scoped lang="scss">
@import '@/common/form-controls.scss';
input { @include native-input-frame; border:1px solid var(--brand-border); }
</style>
